examples.code:
upstream roombook {
    least_conn;
    server 10.0.1.11:8000 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8000 max_fails=3 fail_timeout=10s;
    server 10.0.1.13:8000 max_fails=3 fail_timeout=10s;
}

server {
    listen 443 ssl;
    server_name api.roombook.example;
    ssl_certificate     /etc/ssl/roombook.crt;
    ssl_certificate_key /etc/ssl/roombook.key;

    location / {
        proxy_pass http://roombook;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
